document.schema:
type Query {
  """List countries (public demo API)."""
  countries: [Country!]!
  country(code: ID!): Country
}

type Country {
  code: ID!
  name: String!
  emoji: String
  capital: String
}

document.initialQuery:
query ListCountries {
  countries {
    code
    name
    emoji
  }
}
